async def main():
    async with async_playwright() as p:
        b=await p.chromium.launch(); pg=await b.new_page(viewport={'width':1366,'height':900})
        errs=[]
        pg.on('pageerror',lambda e: errs.append(('PAGEERR',str(e))))
        pg.on('console',lambda m: errs.append(('CONSOLE',m.text)) if m.type=='error' and 'TUNNEL' not in m.text else None)
        await pg.goto(BASE+'/'); await pg.wait_for_timeout(1500)
        for r in routes:
            n=len(errs)
            await pg.evaluate("h=>{location.hash=h}", r); await pg.wait_for_timeout(350)
            txt=await pg.evaluate("document.querySelector('main').innerText.slice(0,80).replace(/\\n/g,' | ')")
            print(f"{r:40s} {txt}")
            for e in errs[n:]: print('   !!', e)
            if r in ('#/c/ch01/cards/cases','#/drugs/fluoxetine','#/nt/dopamine','#/compare/fluoxetine,amitriptyline','#/c/ch01/handout','#/library'):
                await pg.screenshot(path=OUT+'/r_'+r.replace('#/','').replace('/','_').replace(',','-')+'.png')
        await b.close()
asyncio.run(main())
